        var changes = new List<(string Name, string Result)>();
        if (word.Length > 2)
        return (word, changes);
    public static string Stem(string word)
    {
        if (!Cache.TryGetValue(word, out var stem))
        {
            stem = StemmingSteps(word).Stem;
            Cache[word] = stem;
        }
